/* feature-section-v3 */

@keyframes fsv3-highlight-swipe {
  from {
    background-size: 0% 100%;
  }
  to {
    background-size: 100% 100%;
  }
}

@keyframes fsv3-index-settle {
  0% {
    opacity: 0.76;
    transform: translateY(0.02em) scale(0.96);
  }
  65% {
    opacity: 1;
    transform: translateY(-0.015em) scale(1.04);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.fsv3-highlight {
  position: relative;
  line-height: 1;
  background-image: linear-gradient(
    90deg,
    color-mix(in oklch, currentColor 0%, transparent) 0%,
    color-mix(in oklch, currentColor 14%, transparent) 18%,
    color-mix(in oklch, currentColor 14%, transparent) 100%
  );
  background-position: 0 100%;
  background-repeat: no-repeat;
  background-size: 0% 100%;
  animation: fsv3-highlight-swipe 760ms cubic-bezier(0.2, 0.8, 0.2, 1) 1 both;
}

.fsv3-highlight__index {
  display: inline-block;
  animation: fsv3-index-settle 520ms ease-out 1 both;
  animation-delay: inherit;
  transform-origin: center;
}

@media (prefers-reduced-motion: reduce) {
  .fsv3-highlight,
  .fsv3-highlight__index {
    animation: none;
    transform: none;
    background-size: 100% 100%;
  }
}

.fsv3-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

@media (min-width: 768px) {
  .fsv3-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.fsv3-cell {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.fsv3-card {
  position: relative;
  --fsv3-illustration-height: 14rem;
  display: flex;
  height: 100%;
  min-height: 20rem;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  background-color: color-mix(in oklab, var(--muted) 82%, var(--background) 18%);
}

.fsv3-card-top {
  flex: 0 0 var(--fsv3-illustration-height);
  height: var(--fsv3-illustration-height);
  min-height: var(--fsv3-illustration-height);
  max-height: var(--fsv3-illustration-height);
  display: flex;
  flex-direction: column;
}

.fsv3-card-top > * {
  flex: 1 1 0%;
  min-height: 0;
  min-width: 0;
  align-self: stretch;
  width: 100%;
}

.fsv3-card-footer {
  flex: 0 0 auto;
  padding: 0.5rem 0.875rem 0.5625rem;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-height: 0;
}

.fsv3-card-step {
  flex-shrink: 0;
  margin: 0 0 0.25rem;
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  line-height: 1.2;
  color: color-mix(in oklab, var(--foreground) 84%, transparent);
}

.fsv3-card-title {
  flex-shrink: 0;
  margin: 0 0 0.3125rem;
  font-size: 0.95rem;
  line-height: 1.35;
  font-weight: 600;
  color: var(--foreground);
  /* Aligns title baselines across columns without a full 3-line void */
  min-height: calc(0.95rem * 1.35 * 2);
}

.fsv3-card-desc {
  flex: 0 1 auto;
  margin: 0;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--muted-foreground);
}
